    for line in open(path):
        t = line.split()
        if not t:
            continue
        if t[0] == "MACRO":
            cur = t[1]
            macros[cur] = {}
            obs[cur] = collections.Counter()
        elif t[0] == "END" and cur and t[1] == cur:
            cur = None
        elif cur and t[0] == "PIN":
            pin = t[1]
            macros[cur][pin] = {"dir": None, "use": None, "shape": None,
                                "layers": collections.Counter(), "rects": 0}
        elif cur and pin and t[0] == "END" and t[1] == pin:
            pin = None
            layer = None
        elif cur and t[0] == "OBS":
            in_obs = True
            layer = None
        elif cur and in_obs and t[0] == "END":
            in_obs = False
            layer = None
        elif pin is not None and not in_obs:
            if t[0] == "DIRECTION":
                macros[cur][pin]["dir"] = t[1]
            elif t[0] == "USE":
                macros[cur][pin]["use"] = t[1]
            elif t[0] == "SHAPE":
                macros[cur][pin]["shape"] = " ".join(t[1:])
            elif t[0] == "LAYER":
                layer = t[1]
            elif t[0] == "RECT":
                macros[cur][pin]["layers"][layer] += 1
                macros[cur][pin]["rects"] += 1
        elif in_obs:
            if t[0] == "LAYER":
                layer = t[1]
            elif t[0] == "RECT":
                obs[cur][layer] += 1
    return macros, obs


